"""Operator stance baseline from stable measured observations (HF-05).

The baseline is collected only from consecutive, valid, measured observations of
the locked target. Predicted/occluded observations and samples from a different
calibration version are refused. An initial lying or too-low-height target fails
explicitly, and a failed collection stores no baseline (never a fabricated one).

An operator may explicitly confirm an upright stance; that only records
``source=operator_confirmed`` and does not invent measurements or a real body
label. Durations are in device seconds from the source stamps, thresholds carry
their units, and the ready artifact binds an independent baseline version and
the calibration version it was measured under.
"""

import math

import numpy as np

STATE_IDLE = "idle"
STATE_PENDING = "pending"
STATE_READY = "ready"
STATE_FAILED = "failed"
STATES = (STATE_IDLE, STATE_PENDING, STATE_READY, STATE_FAILED)
BASELINE_KIND = "target_stance_baseline"
SCHEMA_VERSION = 1

DEFAULT_SETTINGS = {
    "require_seconds": 3.0,
    "max_duration_s": 10.0,
    "min_samples": 15,
    "min_point_count": 60,
    "max_position_spread_m": 0.25,
    "height_min_m": 0.8,
    "height_max_m": 2.2,
    "max_height_std_m": 0.12,
}


def resolve_settings(settings=None):
    resolved = dict(DEFAULT_SETTINGS)
    for key, value in (settings or {}).items():
        if key not in resolved:
            raise ValueError("unknown baseline setting: " + str(key))
        resolved[key] = value
    for key in ("require_seconds", "max_duration_s", "max_position_spread_m",
                "height_min_m", "height_max_m", "max_height_std_m"):
        resolved[key] = float(resolved[key])
        if not np.isfinite(resolved[key]) or resolved[key] <= 0.0:
            raise ValueError(key + " must be a positive finite number")
    resolved["min_samples"] = int(resolved["min_samples"])
    resolved["min_point_count"] = int(resolved["min_point_count"])
    if resolved["min_samples"] <= 0 or resolved["min_point_count"] <= 0:
        raise ValueError("min_samples and min_point_count must be positive")
    if resolved["height_max_m"] <= resolved["height_min_m"]:
        raise ValueError("height_max_m must be greater than height_min_m")
    if resolved["max_duration_s"] <= resolved["require_seconds"]:
        raise ValueError("max_duration_s must exceed require_seconds")
    return resolved


class StanceBaselineCollector:
    def __init__(self, session_id, settings=None):
        self.session_id = session_id
        self.settings = resolve_settings(settings)
        self.status = STATE_IDLE
        self.reason = None
        self.track_id = None
        self.calibration_version = None
        self.operator_confirmed = False
        self.start_source_s = None
        self.samples = []
        self.baseline = None
        self._baseline_counter = 0

    def start(self, track_id, calibration_version, start_source_s=None,
              operator_confirmed=False):
        self.status = STATE_PENDING
        self.reason = None
        self.track_id = track_id
        self.calibration_version = calibration_version
        self.operator_confirmed = bool(operator_confirmed)
        self.start_source_s = None if start_source_s is None else float(start_source_s)
        self.samples = []
        self.baseline = None
        return self.snapshot()

    def _fail(self, reason):
        self.status = STATE_FAILED
        self.reason = reason
        self.baseline = None
        return self.snapshot()

    def feed(self, observation, source_stamp_s=None, predicted=False, occluded=False):
        if self.status != STATE_PENDING:
            return self.snapshot()
        if observation.get("track_id") != self.track_id:
            return self._fail("target_changed")
        if predicted or occluded:
            self.reason = "observation_not_measured"
            return self.snapshot()
        if observation.get("calibration_version") != self.calibration_version:
            return self._fail("calibration_version_changed")
        if not observation.get("ground_relative"):
            return self._fail("ground_unavailable")
        point_count = observation.get("point_count")
        height = (observation.get("height_m") or {}).get("median")
        position = observation.get("position_m")
        if point_count is None or point_count < self.settings["min_point_count"]:
            return self._fail("low_point_count")
        if height is None or position is None:
            return self._fail("missing_geometry")
        height = float(height)
        start_low = not self.samples and not self.operator_confirmed \
            and height < self.settings["height_min_m"]
        if start_low:
            return self._fail("initial_low_posture")
        if not self.operator_confirmed and (
                height < self.settings["height_min_m"]
                or height > self.settings["height_max_m"]):
            return self._fail("height_out_of_range")
        self.samples.append({
            "source_stamp_s": None if source_stamp_s is None else float(source_stamp_s),
            "point_count": int(point_count),
            "height_m": height,
            "position_m": [float(value) for value in position],
        })
        return self._evaluate()

    def _evaluate(self):
        if not self.samples:
            return self.snapshot()
        heights = np.array([sample["height_m"] for sample in self.samples], dtype=np.float64)
        positions = np.array([sample["position_m"] for sample in self.samples], dtype=np.float64)
        center = np.median(positions, axis=0)
        spread = float(np.max(np.linalg.norm(positions - center, axis=1)))
        height_std = float(np.std(heights))
        duration = None
        if self.start_source_s is not None:
            last = self.samples[-1]["source_stamp_s"]
            if last is not None:
                duration = last - self.start_source_s
        enough = (len(self.samples) >= self.settings["min_samples"]
                  and duration is not None
                  and duration >= self.settings["require_seconds"])
        if enough and spread <= self.settings["max_position_spread_m"] \
                and height_std <= self.settings["max_height_std_m"]:
            return self._ready(duration, center, heights, height_std, spread)
        if duration is not None and duration > self.settings["max_duration_s"]:
            return self._fail("timeout_insufficient_samples")
        if spread > self.settings["max_position_spread_m"]:
            return self._fail("position_unstable")
        if height_std > self.settings["max_height_std_m"]:
            return self._fail("height_unstable")
        return self.snapshot()

    def _ready(self, duration, center, heights, height_std, spread):
        self._baseline_counter += 1
        self.status = STATE_READY
        self.reason = None
        self.baseline = {
            "kind": BASELINE_KIND,
            "schema_version": SCHEMA_VERSION,
            "baseline_version": self._baseline_counter,
            "session_id": self.session_id,
            "track_id": self.track_id,
            "calibration_version": self.calibration_version,
            "status": STATE_READY,
            "unit": "m",
            "source": "operator_confirmed" if self.operator_confirmed else "measured",
            "height_m": {"median": float(np.median(heights)),
                         "p10": float(np.percentile(heights, 10.0)),
                         "p90": float(np.percentile(heights, 90.0)),
                         "std": height_std},
            "position_m": [float(value) for value in center],
            "sample_count": len(self.samples),
            "duration_s": float(duration),
            "position_spread_m": spread,
            "point_count_median": float(np.median(
                [sample["point_count"] for sample in self.samples])),
            "thresholds": {key: self.settings[key] for key in (
                "require_seconds", "min_samples", "min_point_count",
                "max_position_spread_m", "height_min_m", "height_max_m",
                "max_height_std_m")},
            "units": {"length": "m", "time": "s"},
        }
        return self.snapshot()

    def snapshot(self):
        return {
            "status": self.status,
            "reason": self.reason,
            "session_id": self.session_id,
            "track_id": self.track_id,
            "calibration_version": self.calibration_version,
            "sample_count": len(self.samples),
            "operator_confirmed": self.operator_confirmed,
            "baseline": None if self.baseline is None else dict(self.baseline),
        }

"""Board-side selection request/ack backend (HF-05).

Only three actions are accepted: ``select``, ``release`` and
``capture_baseline``. Every request is bound to a ``request_id``, the session,
the source ``time_epoch``, a candidate ``snapshot_id`` and a
``selection_version``; a bare pixel box is never accepted as a metric position.
The backend is the single authority on whether a selection succeeded.

Idempotency: a repeated ``request_id`` with identical content returns the
original ack and is not executed twice; the same id with different content is
rejected. The snapshot cache is bounded, receive time must be monotonic, and an
unknown/stale snapshot, a cross-epoch request or an old selection version is
refused. Ids are only meaningful inside this session.
"""

import json
from collections import deque

try:  # pragma: no cover - import shim
    from core.baseline import StanceBaselineCollector
except ImportError:  # pragma: no cover
    from baseline import StanceBaselineCollector

ACTIONS = ("select", "release", "capture_baseline")
ACK_KIND = "selection_ack"
SCHEMA_VERSION = 1

DEFAULT_SETTINGS = {
    "snapshot_ttl_s": 2.0,
    "request_cache_size": 64,
    "snapshot_cache_size": 16,
}

REASON_UNKNOWN = "unknown_action"
REASON_MISSING_FIELD = "missing_field"
REASON_SESSION_MISMATCH = "session_mismatch"
REASON_CONFLICT = "request_id_conflict"
REASON_NONMONOTONIC = "nonmonotonic_time"
REASON_UNKNOWN_SNAPSHOT = "unknown_snapshot"
REASON_STALE_SNAPSHOT = "stale_snapshot"
REASON_EPOCH_MISMATCH = "epoch_mismatch"
REASON_UNKNOWN_CANDIDATE = "unknown_candidate"
REASON_INSUFFICIENT_QUALITY = "insufficient_candidate_quality"
REASON_STALE_VERSION = "stale_selection_version"
REASON_INVALID_VERSION = "invalid_selection_version"
REASON_NOT_LOCKED = "target_not_locked"
REASON_TRACK_MISMATCH = "track_mismatch"


def resolve_settings(settings=None):
    resolved = dict(DEFAULT_SETTINGS)
    for key, value in (settings or {}).items():
        if key not in resolved:
            raise ValueError("unknown selection setting: " + str(key))
        resolved[key] = value
    if float(resolved["snapshot_ttl_s"]) <= 0.0:
        raise ValueError("snapshot_ttl_s must be positive")
    resolved["snapshot_ttl_s"] = float(resolved["snapshot_ttl_s"])
    resolved["request_cache_size"] = int(resolved["request_cache_size"])
    resolved["snapshot_cache_size"] = int(resolved["snapshot_cache_size"])
    if resolved["request_cache_size"] <= 0 or resolved["snapshot_cache_size"] <= 0:
        raise ValueError("cache sizes must be positive")
    return resolved


class SelectionBackend:
    def __init__(self, session_id, tracker, baseline=None, settings=None):
        self.session_id = session_id
        self.tracker = tracker
        self.baseline = baseline if baseline is not None else StanceBaselineCollector(session_id)
        self.settings = resolve_settings(settings)
        self.time_epoch = tracker.time_epoch if tracker.time_epoch is not None else 0
        self._snapshots = {}
        self._snapshot_order = deque()
        self._requests = {}
        self._request_order = deque()
        self._last_receive_s = None
        self._track_counter = 0

    def set_epoch(self, time_epoch):
        self.time_epoch = int(time_epoch)
        self.tracker.note_epoch(self.time_epoch)

    def register_snapshot(self, snapshot, receive_s):
        snapshot_id = snapshot.get("snapshot_id")
        if not snapshot_id:
            raise ValueError("snapshot needs a snapshot_id")
        self._snapshots[snapshot_id] = {"receive_s": float(receive_s),
                                        "time_epoch": snapshot.get("time_epoch"),
                                        "snapshot": snapshot}
        self._snapshot_order.append(snapshot_id)
        while len(self._snapshot_order) > self.settings["snapshot_cache_size"]:
            self._snapshots.pop(self._snapshot_order.popleft(), None)

    def _ack(self, request, accepted, reason, *, track_id=None, selection_version=None,
             candidate_id=None, baseline=None, idempotent_replay=False):
        return {
            "kind": ACK_KIND,
            "schema_version": SCHEMA_VERSION,
            "request_id": request.get("request_id"),
            "action": request.get("action"),
            "session_id": self.session_id,
            "time_epoch": self.time_epoch,
            "accepted": bool(accepted),
            "reason": reason,
            "track_id": track_id,
            "candidate_id": candidate_id,
            "selection_version": selection_version,
            "baseline": baseline,
            "idempotent_replay": bool(idempotent_replay),
        }

    def _remember(self, request, ack):
        request_id = request["request_id"]
        content = json.dumps(request, sort_keys=True)
        self._requests[request_id] = {"content": content, "ack": ack}
        self._request_order.append(request_id)
        while len(self._request_order) > self.settings["request_cache_size"]:
            self._requests.pop(self._request_order.popleft(), None)

    def handle(self, request, receive_s):
        if not isinstance(request, dict):
            raise ValueError("request must be an object")
        request_id = request.get("request_id")
        if not isinstance(request_id, str) or not request_id:
            return self._ack(request, False, REASON_MISSING_FIELD)
        if not isinstance(receive_s, (int, float)) or receive_s != receive_s:
            return self._ack(request, False, REASON_NONMONOTONIC)
        receive_s = float(receive_s)

        content = json.dumps(request, sort_keys=True)
        cached = self._requests.get(request_id)
        if cached is not None:
            if cached["content"] == content:
                replay = dict(cached["ack"])
                replay["idempotent_replay"] = True
                return replay
            return self._ack(request, False, REASON_CONFLICT)

        action = request.get("action")
        if action not in ACTIONS:
            return self._ack(request, False, REASON_UNKNOWN)
        if request.get("session_id") != self.session_id:
            return self._ack(request, False, REASON_SESSION_MISMATCH)
        if self._last_receive_s is not None and receive_s < self._last_receive_s:
            return self._ack(request, False, REASON_NONMONOTONIC)
        self._last_receive_s = receive_s

        if action == "select":
            ack = self._select(request, receive_s)
        elif action == "release":
            ack = self._release(request)
        else:
            ack = self._capture_baseline(request, receive_s)
        self._remember(request, ack)
        return ack

    def _expected_version(self, request):
        version = request.get("selection_version")
        if version is None:
            return None, self._ack(request, False, REASON_MISSING_FIELD)
        version = int(version)
        current = int(self.tracker.selection_version)
        if version < current:
            return None, self._ack(request, False, REASON_STALE_VERSION)
        if version > current:
            return None, self._ack(request, False, REASON_INVALID_VERSION)
        return current, None

    def _lookup_candidate(self, request, receive_s, require_snapshot=True):
        snapshot_id = request.get("snapshot_id")
        if not snapshot_id:
            return None, self._ack(request, False, REASON_MISSING_FIELD)
        entry = self._snapshots.get(snapshot_id)
        if entry is None:
            return None, self._ack(request, False, REASON_UNKNOWN_SNAPSHOT)
        if receive_s - entry["receive_s"] > self.settings["snapshot_ttl_s"]:
            return None, self._ack(request, False, REASON_STALE_SNAPSHOT)
        requested_epoch = request.get("time_epoch")
        if requested_epoch is None or int(requested_epoch) != self.time_epoch \
                or entry["time_epoch"] != self.time_epoch:
            return None, self._ack(request, False, REASON_EPOCH_MISMATCH)
        candidate_id = request.get("candidate_id")
        if not candidate_id:
            return None, self._ack(request, False, REASON_MISSING_FIELD)
        for candidate in entry["snapshot"].get("candidates", []):
            if candidate.get("candidate_id") == candidate_id:
                return candidate, None
        return None, self._ack(request, False, REASON_UNKNOWN_CANDIDATE)

    def _select(self, request, receive_s):
        current, error = self._expected_version(request)
        if error is not None:
            return error
        candidate, error = self._lookup_candidate(request, receive_s)
        if error is not None:
            return error
        quality = candidate.get("quality") or {}
        if not quality.get("sufficient_points", False):
            return self._ack(request, False, REASON_INSUFFICIENT_QUALITY)
        source_stamp_s = (request.get("snapshot_id") is not None
                          and self._snapshots[request["snapshot_id"]]["snapshot"]
                          .get("source", {}).get("source_stamp_s"))
        self._track_counter += 1
        track_id = "t{:04d}".format(self._track_counter)
        new_version = current + 1
        self.tracker.select(track_id, self.time_epoch, candidate=candidate,
                            calibration_version=request.get("calibration_version"),
                            selection_version=new_version,
                            source_stamp_s=source_stamp_s, receive_s=receive_s)
        return self._ack(request, True, None, track_id=track_id,
                         selection_version=new_version,
                         candidate_id=candidate.get("candidate_id"))

    def _release(self, request):
        current, error = self._expected_version(request)
        if error is not None:
            return error
        requested_track = request.get("track_id")
        if requested_track is not None and requested_track != self.tracker.track_id:
            return self._ack(request, False, REASON_TRACK_MISMATCH,
                             selection_version=current)
        self.tracker.release()
        self.tracker.selection_version = current + 1
        return self._ack(request, True, None, selection_version=current + 1,
                         track_id=None)

    def _capture_baseline(self, request, receive_s):
        current, error = self._expected_version(request)
        if error is not None:
            return error
        if self.tracker.track_status != "locked":
            return self._ack(request, False, REASON_NOT_LOCKED,
                             selection_version=current)
        requested_track = request.get("track_id")
        if requested_track is not None and requested_track != self.tracker.track_id:
            return self._ack(request, False, REASON_TRACK_MISMATCH,
                             selection_version=current)
        start_source_s = request.get("source_stamp_s")
        self.baseline.start(self.tracker.track_id, self.tracker.calibration_version,
                            start_source_s=start_source_s,
                            operator_confirmed=bool(request.get("operator_confirmed")))
        return self._ack(request, True, None, track_id=self.tracker.track_id,
                         selection_version=current,
                         baseline=self.baseline.snapshot())

